html:
{% set logo = frappe.db.get_value('Website Settings', None, 'app_logo') %}
{% set line_items = doc.items or [] %}
{% set service_item_name = frappe.db.get_value('Item', doc.service_item, 'item_name') or doc.service_item %}
{% set company_name = frappe.db.get_value('Company', doc.company, 'company_name') if doc.company else (doc.employer_name or 'phamos GmbH') %}
{% set company_tax_id = frappe.db.get_value('Company', doc.company, 'tax_id') if doc.company else '' %}
{% set customer_name = frappe.db.get_value('Customer', doc.customer, 'customer_name') if doc.customer else (doc.employee_name or '') %}
{% set supplier_address_display = frappe.db.get_value('Address', doc.supplier_address, 'address_display') if doc.supplier_address else '' %}
{% set customer_address_display = frappe.db.get_value('Address', doc.customer_address, 'address_display') if doc.customer_address else '' %}

<style>
:root {
  --ink: #1f2a3d;
  --muted: #6e7d92;
  --line: #d8e1ee;
  --soft: #f4f7fb;
  --brand: #0f4f8a;
  --brand-soft: #eaf2fb;
  --total-bg: #e2eefb;
}

@page {
  size: A4;
  margin: 20mm 20mm 22mm 25mm;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  color: var(--ink);
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 10.7pt;
  line-height: 1.45;
}

.invoice-sheet {
  width: 100%;
}

.header-grid {
  display: table;
  width: 100%;
  border-bottom: 2px solid var(--brand);
  padding-bottom: 6mm;
}

.header-left,
.header-right {
  display: table-cell;
  vertical-align: top;
}

.header-right {
  width: 39%;
  text-align: right;
}

.logo-box {
  min-height: 18mm;
}

.logo-box img {
  max-height: 18mm;
  max-width: 58mm;
}

.company-name {
  margin-top: 2mm;
  font-size: 12pt;
  font-weight: 700;
}

.main-title {
  margin-top: 4mm;
  font-size: 24pt;
  letter-spacing: 1px;
  line-height: 1.1;
  color: var(--brand);
  font-weight: 700;
}

.subtitle {
  margin-top: 1mm;
  color: var(--muted);
  font-size: 9.8pt;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.info-panel {
  display: inline-block;
  text-align: left;
  border: 1px solid var(--line);
  background: var(--soft);
  border-radius: 3px;
  padding: 3.2mm 3.4mm;
  min-width: 67mm;
}

.info-row {
  display: table;
  width: 100%;
  margin-bottom: 1.1mm;
}

.info-row:last-child {
  margin-bottom: 0;
}

.info-label,
.info-value {
  display: table-cell;
  vertical-align: top;
}

.info-label {
  width: 43%;
  color: var(--muted);
  font-size: 9pt;
}

.info-value {
  font-weight: 600;
  font-size: 9.7pt;
}

.section {
  margin-top: 7mm;
}

.section-title {
  margin: 0 0 2.3mm 0;
  color: var(--brand);
  font-size: 10.2pt;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.address-grid {
  display: table;
  width: 100%;
  border-spacing: 0;
}

.address-col {
  display: table-cell;
  width: 50%;
  vertical-align: top;
  border: 1px solid var(--line);
  background: #ffffff;
  border-radius: 3px;
  padding: 4mm 4.2mm;
}

.address-col + .address-col {
  border-left: none;
}

.block-caption {
  margin: 0 0 1.4mm 0;
  font-size: 8.8pt;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.35px;
}

.entity-name {
  margin: 0 0 1.2mm 0;
  font-size: 10.8pt;
  font-weight: 700;
}

.address-text p {
  margin: 0;
}

.panel-grid {
  display: table;
  width: 100%;
  border-spacing: 0;
}

.panel-col {
  display: table-cell;
  width: 50%;
  vertical-align: top;
  border: 1px solid var(--line);
  background: var(--soft);
  padding: 3.8mm 4.2mm;
}

.panel-col + .panel-col {
  border-left: none;
}

.data-row {
  margin-bottom: 1.2mm;
}

.data-row:last-child {
  margin-bottom: 0;
}

.data-key {
  color: var(--muted);
}

.service-box {
  border: 1px solid var(--line);
  background: #ffffff;
  padding: 4mm 4.2mm;
  min-height: 16mm;
  white-space: pre-wrap;
}

.item-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2mm;
}

.item-table thead th {
  background: var(--brand-soft);
  color: #143a61;
  text-align: left;
  font-size: 9.1pt;
  text-transform: uppercase;
  letter-spacing: 0.35px;
  border: 1px solid #cddbee;
  padding: 2.7mm 2.2mm;
}

.item-table tbody td {
  border: 1px solid var(--line);
  padding: 2.9mm 2.2mm;
  vertical-align: top;
}

.item-table tbody tr:nth-child(even) td {
  background: #fbfdff;
}

.col-qty,
.col-rate,
.col-amount {
  text-align: right;
  white-space: nowrap;
}

.col-qty {
  width: 11%;
}

.col-rate,
.col-amount {
  width: 18%;
}

.totals-wrap {
  margin-top: 4.2mm;
  text-align: right;
}

.total-box {
  display: inline-block;
  min-width: 70mm;
  background: var(--total-bg);
  border: 1px solid #b9cde7;
  padding: 3.8mm 4.4mm;
  border-radius: 3px;
}

.total-label {
  color: #234f7d;
  font-size: 9.3pt;
  text-transform: uppercase;
  letter-spacing: 0.35px;
}

.total-value {
  margin-top: 1mm;
  font-size: 16pt;
  line-height: 1.1;
  font-weight: 700;
  color: #0c3d6b;
}

.notes-wrap {
  margin-top: 7mm;
  border-top: 1px solid var(--line);
  padding-top: 3.8mm;
}

.notes-box {
  white-space: pre-wrap;
  margin-bottom: 3.2mm;
}

.payment-instruction {
  color: #334a64;
}

@media print {
  .invoice-sheet {
    page-break-inside: avoid;
  }
}

@media (max-width: 820px) {
  .header-grid,
  .address-grid,
  .panel-grid {
    display: block;
  }

  .header-left,
  .header-right,
  .address-col,
  .panel-col {
    display: block;
    width: 100%;
    border-left: 1px solid var(--line);
    margin-bottom: 2.6mm;
  }

  .header-right {
    text-align: left;
    margin-top: 4mm;
  }

  .main-title {
    font-size: 20pt;
  }

  .info-panel,
  .total-box {
    width: 100%;
    min-width: 0;
  }
}
</style>

<div class="invoice-sheet">
  <div class="header-grid">
    <div class="header-left">
      <div class="logo-box">{% if logo %}<img src="{{ logo }}" alt="Company Logo">{% endif %}</div>
      <div class="company-name">{{ company_name or 'phamos GmbH' }}</div>
      <div class="main-title">INVOICE</div>
      <div class="subtitle">Monthly Salary Invoice</div>
    </div>
    <div class="header-right">
      <div class="info-panel">
        <div class="info-row">
          <div class="info-label">Invoice Number</div>
          <div class="info-value">{{ doc.name }}</div>
        </div>
        <div class="info-row">
          <div class="info-label">Invoice Date</div>
          <div class="info-value">{{ frappe.utils.formatdate(doc.invoice_date) if doc.invoice_date else '' }}</div>
        </div>
        <div class="info-row">
          <div class="info-label">Currency</div>
          <div class="info-value">{{ doc.currency or '' }}</div>
        </div>
        <div class="info-row">
          <div class="info-label">Reference</div>
          <div class="info-value">{{ doc.reference_no or doc.name }}</div>
        </div>
      </div>
    </div>
  </div>

  <div class="section">
    <h3 class="section-title">Supplier & Customer</h3>
    <div class="address-grid">
      <div class="address-col">
        <p class="block-caption">Supplier</p>
        <p class="entity-name">{{ company_name or doc.employer_name or '' }}</p>
        {% if supplier_address_display %}
          <div class="address-text">{{ supplier_address_display }}</div>
        {% else %}
          <div class="address-text">{{ doc.employer_email or '' }}</div>
        {% endif %}
      </div>
      <div class="address-col">
        <p class="block-caption">Customer</p>
        <p class="entity-name">{{ customer_name or doc.employee_name or '' }}</p>
        {% if customer_address_display %}
          <div class="address-text">{{ customer_address_display }}</div>
        {% else %}
          <div class="address-text">{{ doc.personal_email or '' }}</div>
        {% endif %}
      </div>
    </div>
  </div>

  <div class="section">
    <h3 class="section-title">Invoice Information</h3>
    <div class="panel-grid">
      <div class="panel-col">
        <div class="data-row"><span class="data-key">Employee:</span> {{ doc.employee_name or '' }}</div>
        <div class="data-row"><span class="data-key">Customer:</span> {{ customer_name or '' }}</div>
        <div class="data-row"><span class="data-key">Tax ID:</span> {{ company_tax_id or '' }}</div>
      </div>
      <div class="panel-col">
        <div class="data-row"><span class="data-key">Employer:</span> {{ doc.employer_name or company_name or '' }}</div>
        <div class="data-row"><span class="data-key">Personal Email:</span> {{ doc.personal_email or '' }}</div>
        <div class="data-row"><span class="data-key">Status:</span> {{ doc.status or '' }}</div>
      </div>
    </div>
  </div>

  <div class="section">
    <h3 class="section-title">Banking Details</h3>
    <div class="panel-grid">
      <div class="panel-col">
        <div class="data-row"><span class="data-key">Beneficiary:</span> {{ doc.beneficiary_name or '' }}</div>
        <div class="data-row"><span class="data-key">Bank Name:</span> {{ doc.bank_name or '' }}</div>
      </div>
      <div class="panel-col">
        <div class="data-row"><span class="data-key">IBAN:</span> {{ doc.iban or '' }}</div>
        <div class="data-row"><span class="data-key">BIC / SWIFT:</span> {{ doc.bic_swift_code or '' }}</div>
      </div>
    </div>
  </div>

  <div class="section">
    <h3 class="section-title">Description of Service</h3>
    <div class="service-box">{{ doc.description_of_service or '' }}</div>
  </div>

  <div class="section">
    <h3 class="section-title">Invoice Items</h3>
    <table class="item-table">
      <thead>
        <tr>
          <th>Description</th>
          <th class="col-qty">Qty</th>
          <th class="col-rate">Rate</th>
          <th class="col-amount">Amount</th>
        </tr>
      </thead>
      <tbody>
        {% set ns = namespace(total=0) %}
        {% if line_items %}
          {% for item in line_items %}
            {% set item_description = item.description or item.item_name or item.item_code %}
            {% set item_qty = item.qty or 1 %}
            {% set item_rate = item.rate or 0 %}
            {% set item_amount = item.amount or (item_qty * item_rate) %}
            {% set ns.total = ns.total + item_amount %}
            <tr>
              <td>{{ item_description or '' }}</td>
              <td class="col-qty">{{ frappe.format_value(item_qty, {'fieldtype': 'Float'}) }}</td>
              <td class="col-rate">{{ frappe.format_value(item_rate, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
              <td class="col-amount">{{ frappe.format_value(item_amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
            </tr>
          {% endfor %}
        {% else %}
          {% set ns.total = doc.amount or 0 %}
          <tr>
            <td>{{ doc.description_of_service or service_item_name or '' }}</td>
            <td class="col-qty">1</td>
            <td class="col-rate">{{ frappe.format_value(doc.amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
            <td class="col-amount">{{ frappe.format_value(doc.amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
          </tr>
        {% endif %}
      </tbody>
    </table>

    <div class="totals-wrap">
      <div class="total-box">
        <div class="total-label">Total Amount</div>
        <div class="total-value">{{ frappe.format_value(ns.total or doc.amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</div>
      </div>
    </div>
  </div>

  <div class="notes-wrap">
    {% if doc.notes %}
      <div class="notes-box"><strong>Notes</strong><br>{{ doc.notes }}</div>
    {% endif %}
    <div class="payment-instruction">
      Please transfer the invoice amount to the bank account listed above and include invoice number {{ doc.name }} as payment reference.
    </div>
  </div>
</div>
